const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const crypto = require('crypto');
const argon2 = require('argon2');

const app = express();
const server = http.createServer(app);
const io = new Server(server);

// In-memory stores (production would use Redis/DB)
const tenants = new Map();
const sessions = new Map();
const loginAttempts = new Map();

const MAX_ATTEMPTS = 5;
const LOCKOUT_DURATION = 15 * 60 * 1000; // 15 minutes
const SESSION_TTL = 3600000;

function getTenantKey(tenantId, username) {
  return `${tenantId}:${username}`;
}

function generateSessionToken() {
  return crypto.randomBytes(32).toString('hex');
}

function isAccountLocked(tenantId, username) {
  const key = getTenantKey(tenantId, username);
  const record = loginAttempts.get(key);
  if (!record) return false;
  if (record.attempts >= MAX_ATTEMPTS) {
    const elapsed = Date.now() - record.lastAttempt;
    if (elapsed < LOCKOUT_DURATION) return true;
    loginAttempts.delete(key);
    return false;
  }
  return false;
}

function recordFailedAttempt(tenantId, username) {
  const key = getTenantKey(tenantId, username);
  const record = loginAttempts.get(key) || { attempts: 0, lastAttempt: 0 };
  record.attempts += 1;
  record.lastAttempt = Date.now();
  loginAttempts.set(key, record);
}

function resetAttempts(tenantId, username) {
  const key = getTenantKey(tenantId, username);
  loginAttempts.delete(key);
}

async function authenticateUser(tenantId, username, password) {
  const tenant = tenants.get(tenantId);
  if (!tenant) return { success: false, error: 'Invalid tenant' };

  if (isAccountLocked(tenantId, username)) {
    return { success: false, error: 'Account temporarily locked' };
  }

  const user = tenant.users.get(username);
  if (!user) {
    recordFailedAttempt(tenantId, username);
    return { success: false, error: 'Invalid credentials' };
  }

  const valid = await argon2.verify(user.passwordHash, password);
  if (!valid) {
    recordFailedAttempt(tenantId, username);
    return { success: false, error: 'Invalid credentials' };
  }

  resetAttempts(tenantId, username);
  return { success: true, user: { username, tenantId, role: user.role } };
}

function validateSession(token) {
  const session = sessions.get(token);
  if (!session) return null;
  if (Date.now() - session.createdAt > SESSION_TTL) {
    sessions.delete(token);
    return null;
  }
  return session;
}

// Cross-tenant session migration for SSO federation
function migrateSession(sourceToken, targetTenantId, requestingSession) {
  const sourceSession = sessions.get(sourceToken);
  if (!sourceSession) return null;

  // Verify the requesting user owns the source session
  if (sourceSession.username !== requestingSession.username ||
      sourceSession.tenantId !== requestingSession.tenantId) {
    return null;
  }

  const targetTenant = tenants.get(targetTenantId);
  if (!targetTenant) return null;

  // Check if user exists in target tenant via federation
  const federatedUser = targetTenant.users.get(sourceSession.username);
  if (!federatedUser) return null;

  // Create new session in target tenant context
  const newToken = generateSessionToken();
  const newSession = {
    username: sourceSession.username,
    tenantId: targetTenantId,
    role: federatedUser.role,
    createdAt: Date.now(),
    federatedFrom: sourceSession.tenantId
  };
  sessions.set(newToken, newSession);
  return { token: newToken, session: newSession };
}

io.on('connection', (socket) => {
  let currentSession = null;

  socket.on('auth', async (data, callback) => {
    if (!data || !data.tenantId || !data.username || !data.password) {
      return callback({ success: false, error: 'Missing fields' });
    }

    const result = await authenticateUser(data.tenantId, data.username, data.password);
    if (!result.success) return callback(result);

    const token = generateSessionToken();
    currentSession = {
      username: result.user.username,
      tenantId: result.user.tenantId,
      role: result.user.role,
      createdAt: Date.now()
    };
    sessions.set(token, currentSession);
    socket.join(`tenant:${data.tenantId}`);
    callback({ success: true, token });
  });

  socket.on('resume', (data, callback) => {
    if (!data || !data.token) return callback({ success: false });
    const session = validateSession(data.token);
    if (!session) return callback({ success: false, error: 'Invalid session' });
    currentSession = session;
    socket.join(`tenant:${session.tenantId}`);
    callback({ success: true, username: session.username });
  });

  socket.on('federate', (data, callback) => {
    if (!currentSession) return callback({ success: false, error: 'Not authenticated' });
    if (!data || !data.targetTenantId || !data.sourceToken) {
      return callback({ success: false, error: 'Missing fields' });
    }

    const migrated = migrateSession(data.sourceToken, data.targetTenantId, currentSession);
    if (!migrated) return callback({ success: false, error: 'Federation failed' });

    socket.leave(`tenant:${currentSession.tenantId}`);
    currentSession = migrated.session;
    socket.join(`tenant:${data.targetTenantId}`);
    callback({ success: true, token: migrated.token, role: migrated.session.role });
  });

  socket.on('message', (data, callback) => {
    if (!currentSession) return callback({ success: false, error: 'Not authenticated' });
    if (!data || !data.room || !data.content) {
      return callback({ success: false, error: 'Missing fields' });
    }

    const roomKey = `tenant:${currentSession.tenantId}:${data.room}`;
    io.to(roomKey).emit('message', {
      from: currentSession.username,
      content: data.content,
      timestamp: Date.now()
    });
    callback({ success: true });
  });

  socket.on('join_room', (data, callback) => {
    if (typeof callback !== 'function') return;
    if (!currentSession) return callback({ success: false });
    if (!data || typeof data.room !== 'string' || data.room.length === 0) {
      return callback({ success: false, error: 'Invalid room' });
    }
    const roomKey = `tenant:${currentSession.tenantId}:${data.room}`;
    socket.join(roomKey);
    callback({ success: true });
  });
});

// Tenant provisioning endpoint (would be admin-protected in production)
app.use(express.json());
app.post('/api/tenants/:id/users', async (req, res) => {
  const { id } = req.params;
  const { username, password, role } = req.body;

  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ success: false, error: 'Invalid input' });
  }

  if (!tenants.has(id)) {
    tenants.set(id, { users: new Map(), config: {} });
  }

  const tenant = tenants.get(id);
  const passwordHash = await argon2.hash(password);
  const safeRole = ['member', 'moderator'].includes(role) ? role : 'member';
  tenant.users.set(username, { passwordHash, role: safeRole });
  res.json({ success: true });
});

server.listen(3000);
module.exports = { server, io, tenants, sessions, loginAttempts };
